package fit.iuh.foodgobackend.cart;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import fit.iuh.foodgobackend.common.*;
import fit.iuh.foodgobackend.catalog.*;
import fit.iuh.foodgobackend.account.UserPrincipal;
import java.util.*;
class CartTests {
 @Test void unavailableRestaurantIsRejected(){var db=mock(JpaSql.class);when(db.required("SELECT * FROM foods WHERE id=? FOR UPDATE",1L)).thenReturn(Data.m("id",1L,"available",true,"restaurant_id",2L));when(db.required("SELECT available FROM restaurants WHERE id=? FOR UPDATE",2L)).thenReturn(Map.of("available",false));var p=new PricingService(db,mock(CatalogService.class));assertEquals("ITEM_UNAVAILABLE",assertThrows(ApiException.class,()->p.line(1,1,"",List.of())).code);}
 @Test void duplicateOptionsRejected(){var p=new PricingService(mock(JpaSql.class),mock(CatalogService.class));assertEquals("INVALID_OPTIONS",assertThrows(ApiException.class,()->p.line(1,1,"",List.of(2L,2L))).code);}
 @Test void invalidLinesRemainVisibleAndStrictPricingStillRejects(){var db=mock(JpaSql.class);when(db.rows("SELECT * FROM cart_items WHERE cart_id=? ORDER BY food_id,id",4L)).thenReturn(List.of(Data.m("id",5L,"food_id",1L,"quantity",2,"note","test")));when(db.rows("SELECT option_value_id FROM cart_item_options WHERE cart_item_id=? ORDER BY option_value_id",5L)).thenReturn(List.of());when(db.required("SELECT * FROM foods WHERE id=? FOR UPDATE",1L)).thenReturn(Data.m("available",false));when(db.one("SELECT name,image_code FROM foods WHERE id=?",1L)).thenReturn(Map.of("name","Test","image_code",""));var p=new PricingService(db,mock(CatalogService.class));var row=p.displayLines(4).getFirst();assertEquals("5",row.get("id"));assertEquals(false,row.get("valid"));assertEquals(false,row.get("available"));assertEquals(row.get("invalidMessage"),row.get("validationMessage"));assertNull(row.get("unitPrice"));assertEquals(0,((Number)row.get("lineTotal")).intValue());assertEquals("ITEM_UNAVAILABLE",row.get("invalidReason"));assertThrows(ApiException.class,()->p.lines(4));}
 @Test void oldVersionNeverWrites(){var db=mock(JpaSql.class);when(db.one("SELECT * FROM carts WHERE customer_id=? FOR UPDATE",7L)).thenReturn(Data.m("id",4L,"version",2L));var p=mock(PricingService.class);var s=new CartService(db,p);var u=new UserPrincipal(7,"test","CUSTOMER",null,"test");assertEquals("CART_VERSION_CONFLICT",assertThrows(ApiException.class,()->s.add(u,new CartService.ItemInput(1L,List.of(),"",1,1,false),null)).code);verifyNoInteractions(p);assertTrue(mockingDetails(db).getInvocations().stream().noneMatch(i->i.getMethod().getName().equals("update")));}
 @Test void changingRestaurantRequiresExplicitConfirmationBeforeDeletion(){var db=mock(JpaSql.class);when(db.one("SELECT * FROM carts WHERE customer_id=? FOR UPDATE",7L)).thenReturn(Data.m("id",4L,"version",2L,"restaurant_id",3L));var p=mock(PricingService.class);when(p.line(1L,1,"",List.of())).thenReturn(Data.m("restaurantId",9L));var s=new CartService(db,p);var u=new UserPrincipal(7,"test","CUSTOMER",null,"test");assertEquals("RESTAURANT_REPLACE_REQUIRED",assertThrows(ApiException.class,()->s.add(u,new CartService.ItemInput(1L,List.of(),"",1,2,false),null)).code);assertTrue(mockingDetails(db).getInvocations().stream().noneMatch(i->i.getMethod().getName().equals("update")));}
 @Test void bothCartReadersExposeSameInvalidRowAndStrictPricingRejects(){var db=mock(JpaSql.class);when(db.rows("SELECT * FROM cart_items WHERE cart_id=? ORDER BY food_id,id",4L)).thenReturn(List.of(Data.m("id",5L,"food_id",1L,"quantity",2,"note","test")));when(db.rows("SELECT option_value_id FROM cart_item_options WHERE cart_item_id=? ORDER BY option_value_id",5L)).thenReturn(List.of());when(db.required("SELECT * FROM foods WHERE id=? FOR UPDATE",1L)).thenThrow(new ApiException(404,"NOT_FOUND","Missing food"));var p=new PricingService(db,mock(CatalogService.class));assertEquals(p.displayLines(4),p.cartLines(4));assertEquals(false,p.cartLines(4).getFirst().get("available"));assertEquals("5",p.cartLines(4).getFirst().get("id"));assertThrows(ApiException.class,()->p.lines(4));}
}
